 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            # A framed object has a complete, single-color rectangular boundary.
            border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if len(border) >= 8 and all(grid[y][x] == color for y,x in border):
                interior = [(y,x) for y in range(r0+1,r1) for x in range(c0+1,c1)]
                objects.append((color,r0,r1,c0,c1,interior,cells))
    sources = []
    for obj in objects:
        color,r0,r1,c0,c1,interior,cells = obj
        if any(grid[y][x] == color for y,x in interior):
            sources.append(obj)
    if not sources:
        return out
    # The patterned frame supplies its interior bitmap to all same-sized blank frames.
    src = sources[0]
    scolor,sr0,sr1,sc0,sc1,_,_ = src
    bitmap = [[grid[y][x] == scolor for x in range(sc0+1,sc1)] for y in range(sr0+1,sr1)]
    sh, sw = len(bitmap), len(bitmap[0]) if bitmap else 0
    for color,r0,r1,c0,c1,interior,cells in objects:
        if (color,r0,r1,c0,c1) == (scolor,sr0,sr1,sc0,sc1):
            continue
        th, tw = r1-r0-1, c1-c0-1
        if th == sh and tw == sw:
            for i in range(th):
                for j in range(tw):
                    out[r0+1+i][c0+1+j] = color if bitmap[i][j] else 0
        else:
            # Frames of another size are not part of this pattern group.
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if out[y][x] == color:
                        out[y][x] = 0
    return out
