            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            objs.append((color,r0,r1,c0,c1,set(cells)))
    # Big rectangular frames are hollow border rectangles with a nonempty interior.
    frames=[]
    for color,r0,r1,c0,c1,cells in objs:
