    # Among frames, one has a pattern in its interior. This acts as a stencil for
    # the other frame(s) with exactly the same interior dimensions.
    src=None
    for color,r0,r1,c0,c1 in frames:
        if any(grid[r][c]==color for r in range(r0+1,r1) for c in range(c0+1,c1)):
