        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==col]
        if not pts: continue
        r0=min(r for r,c in pts);r1=max(r for r,c in pts);c0=min(c for r,c in pts);c1=max(c for r,c in pts)
        edge={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if r in (r0,r1) or c in (c0,c1)}
        if len(edge)>=8 and all(grid[r][c]==col for r,c in edge): frames.append((col,r0,r1,c0,c1))
    # The 7-like patterned object is non-frame. Its full bounding-box occupancy is
    # used as bitmap, copied to the frame with equal interior dimensions.
    comps=[];seen=set()
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==0 or (r,c) in seen: continue
        stack=[(r,c)];seen.add((r,c));cells=set()
        while stack:
          y,x=stack.pop();cells.add((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==col:seen.add((ny,nx));stack.append((ny,nx))
        r0=min(y for y,x in cells);r1=max(y for y,x in cells);c0=min(x for y,x in cells);c1=max(x for y,x in cells)
        comps.append((col,r0,r1,c0,c1,cells))
    for scol,sr0,sr1,sc0,sc1,cells in comps:
        # Exclude any component that forms a complete rectangular frame.
        bh,bw=sr1-sr0+1,sc1-sc0+1
        edge={(y,x) for y in range(sr0,sr1+1) for x in range(sc0,sc1+1) if y in (sr0,sr1) or x in (sc0,sc1)}
        if edge.issubset(cells): continue
        bitmap=[[(r,c) in cells for c in range(sc0,sc1+1)] for r in range(sr0,sr1+1)]
        for tcol,tr0,tr1,tc0,tc1 in frames:
