    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    frames = []
    # A framed object is a color whose bounding box has a complete rectangular border.
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        border = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if len(border) >= 8 and all(grid[r][c] == color for r, c in border):
            frames.append((color, r0, r1, c0, c1))

    # A frame with a nonempty interior is the stencil. Copy its binary interior
    # pattern to every other frame with the same interior dimensions, recoloring
    # the marks to the target frame's color.
    for source in frames:
        scolor, sr0, sr1, sc0, sc1 = source
        sh, sw = sr1 - sr0 - 1, sc1 - sc0 - 1
        if sh <= 0 or sw <= 0:
            continue
        pattern = [[grid[r][c] == scolor for c in range(sc0 + 1, sc1)]
                   for r in range(sr0 + 1, sr1)]
        if not any(any(row) for row in pattern):
            continue
        for target in frames:
            if target == source:
                continue
            tcolor, tr0, tr1, tc0, tc1 = target
            if tr1 - tr0 - 1 != sh or tc1 - tc0 - 1 != sw:
                continue
            for i in range(sh):
                for j in range(sw):
                    out[tr0 + 1 + i][tc0 + 1 + j] = tcolor if pattern[i][j] else 0
    return out
