    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def components(color):
        seen = set(); result = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]; seen.add((r, c)); cells = set()
                while stack:
                    y, x = stack.pop(); cells.add((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                r0=min(y for y,x in cells); r1=max(y for y,x in cells)
                c0=min(x for y,x in cells); c1=max(x for y,x in cells)
                result.append((r0,r1,c0,c1,cells))
        return result

    # Find solid rectangular frames, and irregular/marked boxed motifs.
    frames=[]
    for color in range(1,10):
        for r0,r1,c0,c1,cells in components(color):
            border={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                    if r in (r0,r1) or c in (c0,c1)}
            if len(border)>=8 and border.issubset(cells):
                frames.append((color,r0,r1,c0,c1,cells))

    # Motif frames are paired to a blank canvas of matching outside dimensions.
    # Try identity and quarter-turn orientations; this covers the rectangular demos.
    used_sources=set(); used_targets=set()
    for source in frames:
        scol,sr0,sr1,sc0,sc1,scells=source
        sh,sw=sr1-sr0-1,sc1-sc0-1
        if sh<=0 or sw<=0: continue
        bitmap=[[grid[sr0+1+i][sc0+1+j]==scol for j in range(sw)] for i in range(sh)]
        if not any(any(row) for row in bitmap): continue
        candidates=[]
        for target in frames:
            tcol,tr0,tr1,tc0,tc1,tcells=target
            if target is source: continue
            th,tw=tr1-tr0-1,tc1-tc0-1
            if (sh,sw)==(th,tw):
                candidates.append((0,target,bitmap))
            if (sw,sh)==(th,tw):
                rot=[list(row) for row in zip(*bitmap[::-1])]
                candidates.append((1,target,rot))
        # Prefer exact match, then closest center among targets.
        if candidates:
            def score(item):
                penalty,target,_=item
                _,tr0,tr1,tc0,tc1,_=target
                return (penalty, abs((sr0+sr1)-(tr0+tr1))+abs((sc0+sc1)-(tc0+tc1)))
            _,target,pattern=min(candidates,key=score)
            tcol,tr0,tr1,tc0,tc1,tcells=target
            for i,row in enumerate(pattern):
                for j,on in enumerate(row):
                    out[tr0+1+i][tc0+1+j]=tcol if on else 0
            # The patterned box is consumed after its design is transferred.
            for r,c in scells: out[r][c]=0
    return out
