            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            border = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                      if y in (r0, r1) or x in (c0, c1)}
            if len(border) >= 8 and border.issubset(cells):
                objects.append((color, r0, r1, c0, c1, cells))
    # A framed object containing its own color inside is a stencil. Copy its inner
    # bitmap into every other frame with the same inner dimensions; retain the source.
    frames = objects[:]
    for src in frames:
        scol, sr0, sr1, sc0, sc1, _ = src
        ih, iw = sr1 - sr0 - 1, sc1 - sc0 - 1
        if ih <= 0 or iw <= 0:
            continue
        bitmap = [[grid[sr0 + 1 + i][sc0 + 1 + j] == scol for j in range(iw)]
                  for i in range(ih)]
