            tcol, tr0, tr1, tc0, tc1, _ = target
            if tr1 - tr0 - 1 != ih or tc1 - tc0 - 1 != iw:
                continue
            for i in range(ih):
                for j in range(iw):
                    out[tr0 + 1 + i][tc0 + 1 + j] = tcol if bitmap[i][j] else 0
    return out
